        estado.setLabel("Estado");estado.setItems("Activos","Inactivos","Todos");estado.setValue("Activos");buscar.addValueChangeListener(e->{if(e.isFromClient())reiniciar();});estado.addValueChangeListener(e->{if(e.isFromClient())reiniciar();});
