    private void configurarGrid(){grid.addColumn(ClienteDto::nombreVisible).setHeader("Cliente").setFlexGrow(1);grid.addColumn(x->value(x.identificacion())).setHeader("Identificación").setAutoWidth(true);
        grid.addColumn(x->value(x.telefono())).setHeader("Teléfono").setAutoWidth(true);grid.addColumn(x->value(x.correo())).setHeader("Correo").setAutoWidth(true);grid.addColumn(x->value(x.condicionPagoNombre())).setHeader("Condición").setAutoWidth(true);
        grid.addComponentColumn(x->badge(x.activo())).setHeader("Estado").setAutoWidth(true);grid.addComponentColumn(this::acciones).setHeader("Acciones").setAutoWidth(true).setFlexGrow(0);grid.setAllRowsVisible(true);grid.addClassName("cc-auto-grid");grid.setEmptyStateText("No hay clientes registrados.");}
    private Component acciones(ClienteDto c){HorizontalLayout row=actions();row.add(new AppActionButton(ActionType.VIEW,ButtonSize.GRID_ACTION,"Ver cliente",e->detalle(c.id())));if(puede("clientes.editar"))row.add(new AppActionButton(ActionType.EDIT,ButtonSize.GRID_ACTION,"Editar cliente",e->formulario(c.id())));if(c.activo()&&puede("clientes.desactivar"))row.add(new AppActionButton(ActionType.DEACTIVATE,ButtonSize.GRID_ACTION,"Desactivar cliente",e->confirmarEstado(c)));if(!c.activo()&&puede("clientes.activar"))row.add(new AppActionButton(ActionType.ACTIVATE,ButtonSize.GRID_ACTION,"Activar cliente",e->confirmarEstado(c)));return row;}
    private void cargar(){try{var request=paginacion.currentRequest();var page=service.buscar(buscar.getValue(),estadoFiltro(),request.page(),request.size());grid.setItems(page.getContent());paginacion.setTotal(page.getTotalElements());grid.setEmptyStateText(buscar.getValue().isBlank()?"No hay clientes registrados.":"No se encontraron clientes con los filtros seleccionados.");}catch(RuntimeException ex){error(ex,"No fue posible cargar los clientes.");}}
    private void reiniciar(){paginacion.reset();cargar();}private Boolean estadoFiltro(){return switch(estado.getValue()==null?"Activos":estado.getValue()){case"Inactivos"->false;case"Todos"->null;default->true;};}

