        ComboBox<ClienteCatalogosDto.MonedaOpcion> moneda=combo("Moneda preferida",cat.monedas());moneda.setItemLabelGenerator(x->x.codigo()+" · "+x.nombre());moneda.setRequiredIndicatorVisible(true);
        IntegerField dias=new IntegerField("Días de crédito");dias.setMin(0);BigDecimalField limite=new BigDecimalField("Límite de crédito");limite.addBlurListener(e->{if(limite.getValue()!=null)limite.setValue(limite.getValue().setScale(2,RoundingMode.HALF_UP));});
