        if(actual==null){persona.setValue(TipoPersonaCliente.JURIDICA);tipoId.setValue(TipoIdentificacionCliente.RNC);select(moneda,cat.monedas(),cat.monedaBaseId(),ClienteCatalogosDto.MonedaOpcion::id);cat.condiciones().stream().filter(x->x.tipo()==TipoCondicionPago.CASH).findFirst().or(()->cat.condiciones().stream().findFirst()).ifPresent(condicion::setValue);dias.setValue(0);limite.setValue(BigDecimal.ZERO);control.setValue(ControlLimiteCredito.NO_CONTROLAR);tipoDireccion.setValue(TipoDireccionCliente.FISCAL);pais.setValue("República Dominicana");}
