        boolean manageCredit=puede("clientes.credito.editar"),manageAddress=actual==null||puede("clientes.direcciones.administrar");dias.setReadOnly(!manageCredit);limite.setReadOnly(!manageCredit);control.setReadOnly(!manageCredit);for(Component field:List.of(tipoDireccion,pais,provincia,ciudad,sector,direccion,postal))field.getElement().setProperty("disabled",!manageAddress);
